using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    [Fact]
    public async Task EvaluateGoldenDataset()
    {
        Assert.True(File.Exists(GoldenPath), $"Golden file not found at {GoldenPath}");

        var json = await File.ReadAllTextAsync(GoldenPath);
        var scenarios = JsonSerializer.Deserialize<List<GoldenScenario>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true });

        Assert.NotNull(scenarios);
        Assert.NotEmpty(scenarios);

        foreach (var scenario in scenarios)
        {
            Assert.False(string.IsNullOrWhiteSpace(scenario.Id),
                "Each golden scenario must have an id.");
            Assert.False(string.IsNullOrWhiteSpace(scenario.UserMessage),
                $"Scenario '{scenario.Id}' must have a user_message.");
            Assert.NotEmpty(scenario.ExpectedTraits);
        }
    }
}

public sealed class GoldenScenario
{
    public string Id { get; set; } = string.Empty;

    [System.Text.Json.Serialization.JsonPropertyName("user_message")]
    public string UserMessage { get; set; } = string.Empty;

    [System.Text.Json.Serialization.JsonPropertyName("expected_traits")]
    public List<string> ExpectedTraits { get; set; } = new();
}

